public protocol XeniaClientProtocol: AnyObject, Sendable {
    
    func addNotificationKeyword(keyword: String) async throws 
    
    func block(userId: String) async throws 
    
    /**
     * People I've blocked (ignored): their messages and invitations don't reach me.
     */
    func blockedPeople() async throws  -> [Person]
    
    /**
     * The IDs of people I've blocked, from what this device already knows (no request).
     */
    func blockedUserIds() async  -> [String]
    
    /**
     * Removes downloaded photos and files. Messages, keys and settings stay.
     */
    func clearMediaCache() async throws 
    
    /**
     * Words that notify like a mention, from the account's push rules (shared by every device).
     */
    func notificationKeywords() async throws  -> [String]
    
    func removeAvatar() async throws 
    
    func removeNotificationKeyword(keyword: String) async throws 
    
    /**
     * Uploads a new profile photo (JPEG or PNG bytes) and uses it.
     */
    func setAvatar(data: Data, mimetype: String) async throws 
    
    /**
     * Downloaded media in the SDK's media store, plus files saved for Quick Look and sharing.
     */
    func storageUsage() async  -> StorageUsage
    
    func unblock(userId: String) async throws 
    
    func acceptInvite(roomId: String) async throws 
    
    /**
     * The signed-in account, if any.
     */
    func account()  -> Account?
    
    /**
     * Checks what a typed server address offers, for the sign-in screen.
     */
    func checkServer(address: String) async throws  -> ServerInfo
    
    /**
     * Creates an encrypted group with a name and people. Returns the room ID.
     */
    func createGroup(name: String, userIds: [String]) async throws  -> String
    
    func declineInvite(roomId: String) async throws 
    
    /**
     * The server the sign-in screen starts with.
     */
    func defaultServer()  -> String
    
    /**
     * Chats and rooms in one list (the unified view), with the same rules as `filter_rooms`.
     */
    func filterAllRooms(rooms: [RoomSummary], filter: ListFilter, query: String)  -> [RoomSummary]
    
    /**
     * Filters a list the app already holds (the same rules as `rooms`).
     */
    func filterRooms(rooms: [RoomSummary], scope: Scope, filter: ListFilter, query: String)  -> [RoomSummary]
    
    func invite(roomId: String, userIds: [String]) async throws 
    
    /**
     * Joins "#room:server" or "!id:server". Returns the room ID.
     */
    func join(address: String) async throws  -> String
    
    func leave(roomId: String) async throws 
    
    /**
     * Unsent text for a conversation or thread.
     */
    func loadDraft(roomId: String, threadRoot: String?) async  -> String?
    
    /**
     * Marks every unread conversation in a list (or everywhere) read.
     */
    func markAllRead(scope: Scope?) async throws 
    
    /**
     * Marks a conversation read (and clears a manual unread flag).
     */
    func markRead(roomId: String) async throws 
    
    /**
     * Joined and invited members, sorted by name.
     */
    func members(roomId: String) async throws  -> [Member]
    
    /**
     * The app went to the background (iOS suspends it; sync stops cleanly first).
     */
    func pause() async 
    
    /**
     * A person's profile, for a Matrix ID typed in full.
     */
    func profile(userId: String) async throws  -> Person
    
    /**
     * Public rooms on my server, matching `query`.
     */
    func publicRooms(query: String) async throws  -> [DirectoryRoom]
    
    /**
     * Comes back signed in if a session was saved. Reports `SignedIn` or `SignedOut`.
     */
    func restore() async 
    
    /**
     * The app came back: sync picks up where it left off.
     */
    func resume() async 
    
    /**
     * The conversations one list shows, from the latest snapshot.
     */
    func rooms(scope: Scope, filter: ListFilter, query: String)  -> [RoomSummary]
    
    /**
     * Keeps unsent text; empty text clears the draft.
     */
    func saveDraft(roomId: String, threadRoot: String?, text: String) async 
    
    /**
     * People in the server's user directory.
     */
    func searchPeople(query: String) async throws  -> [Person]
    
    func setDisplayName(name: String) async throws 
    
    func setFavourite(roomId: String, favourite: Bool) async throws 
    
    /**
     * Moves a pin: saves its place among the others, so every device shows the same order.
     */
    func setFavouriteOrder(roomId: String, order: Double) async throws 
    
    /**
     * Flags a conversation unread (or clears the flag).
     */
    func setMarkedUnread(roomId: String, unread: Bool) async throws 
    
    /**
     * What's on screen and how this device notifies, for deciding notifications.
     */
    func setNotificationContext(context: NotificationContext) 
    
    func setNotificationMode(roomId: String, mode: NotificationMode) async throws 
    
    func setRoomName(roomId: String, name: String) async throws 
    
    func setRoomTopic(roomId: String, topic: String) async throws 
    
    /**
     * Whether reading a conversation tells the people in it. Off, Xenia still marks it read,
     * with a private receipt only my own devices see.
     */
    func setSendReadReceipts(enabled: Bool) 
    
    /**
     * Whether conversations show people joining, leaving and changing their names. Takes
     * effect in conversations opened after the change.
     */
    func setShowMembershipChanges(show: Bool) 
    
    /**
     * Signs in with a username (or full Matrix ID) and password.
     */
    func signIn(server: String, username: String, password: String) async throws  -> Account
    
    /**
     * Signs out: tells the server, then forgets the session and its stores on this device.
     */
    func signOut() async 
    
    /**
     * Opens the existing chat with someone, or starts an encrypted one. Returns the room ID.
     */
    func startDirectChat(userId: String) async throws  -> String
    
    /**
     * Conversations in a scope that want attention, for badges.
     */
    func unreadTotal(scope: Scope)  -> UInt32
    
    /**
     * Turns on chat backup. Returns the new recovery key, which the person must keep.
     */
    func enableBackup() async throws  -> String
    
    /**
     * Where backup and verification stand right now.
     */
    func encryptionStatus() async throws  -> EncryptionStatus
    
    /**
     * Unlocks backup on this device with the recovery key (spaces and case don't matter).
     */
    func recover(recoveryKey: String) async throws 
    
    /**
     * Replaces the recovery key (the old one stops working). Returns the new key.
     */
    func resetRecoveryKey() async throws  -> String
    
    /**
     * Joins a room from a link, asking the link's servers when mine doesn't know it. Returns
     * the room ID.
     */
    func joinLink(address: String, via: [String]) async throws  -> String
    
    /**
     * The joined room a link's address names (an ID, or an alias any joined room carries), or
     * `None` when I'm not in it.
     */
    func joinedRoom(address: String) async throws  -> String?
    
    /**
     * What a link shows, read by the homeserver so the site never sees this device. `None`
     * when the page has nothing to show.
     */
    func linkPreview(url: String) async throws  -> LinkPreview?
    
    /**
     * A square avatar thumbnail, `size_px` on a side (ask for 2x or 3x the point size).
     */
    func loadAvatar(mxcUrl: String, sizePx: UInt32) async throws  -> Data
    
    /**
     * The whole file behind a message, decrypted.
     */
    func loadMedia(source: String) async throws  -> Data
    
    /**
     * A photo scaled to fit `width_px` by `height_px`. Encrypted photos can't be thumbnailed by
     * the server, so they come at full size.
     */
    func loadThumbnail(source: String, widthPx: UInt32, heightPx: UInt32) async throws  -> Data
    
    /**
     * Saves the file behind a message under its own name in the cache, for Quick Look, sharing
     * and dragging out. Returns its path.
     */
    func saveMedia(source: String, filename: String) async throws  -> String
    
    /**
     * Messages in a conversation that mention me, newest first, at most `limit`. Fails only
     * when the server can't be asked and this device has nothing to show.
     */
    func mentions(roomId: String, limit: UInt32) async throws  -> [MentionHit]
    
    /**
     * Registers (or refreshes) this device's pusher. Safe to call on every launch: the server
     * replaces a pusher with the same key and app ID.
     */
    func registerPusher(registration: PushRegistration) async throws 
    
    /**
     * Stops pushes to this device (notifications turned off, or signing out).
     */
    func unregisterPusher(pushKey: String, appId: String) async throws 
    
    /**
     * Starts a message search: words, filters, or both. Ask for batches with `next_batch`.
     * Filters without words only work in one conversation, where the history can be walked.
     */
    func searchMessages(query: String, scope: SearchScope, filters: SearchFilters) async throws  -> MessageSearch
    
    /**
     * Follows a room's threads. The first page loads right away.
     */
    func threadList(roomId: String, listener: ThreadListListener) async throws  -> ThreadList
    
    /**
     * Sends a message without opening the conversation (a reply from a notification).
     */
    func sendMessage(roomId: String, message: ComposedMessage) async throws 
    
    /**
     * Opens a conversation, a thread or a moment in the past. The first screenful loads right
     * away; updates arrive on `listener` until the controller is dropped.
     */
    func timeline(roomId: String, focus: TimelineFocus, listener: TimelineListener) async throws  -> TimelineController
    
    /**
     * Checks the account password with the server, changing nothing (it asks to sign out no
     * devices, which needs the password). For keeping the password where other devices sign in
     * with it. A server that doesn't ask for it there can't check it, and it passes.
     */
    func checkPassword(password: String) async throws 
    
    /**
     * Picks up a request someone sent (from `on_verification_request`).
     */
    func incomingVerification(userId: String, flowId: String, listener: VerificationListener) async throws  -> Verification
    
    /**
     * Whether I've verified someone.
     */
    func personTrust(userId: String) async  -> PersonTrust
    
    func renameSession(deviceId: String, name: String) async throws 
    
    /**
     * Starts encryption over when no other device or recovery key can verify this one: new keys
     * that make this device the verified one, and a new recovery key (returned, to show once).
     * Other devices need verifying again, and messages only the old backup held stay unreadable.
     */
    func resetEncryptionIdentity(password: String) async throws  -> String
    
    /**
     * The account's signed-in devices, this one first, then most recently used.
     */
    func sessions() async throws  -> [Session]
    
    /**
     * Signs other devices out. Servers ask for the account password first:
     * `PasswordRequired` means call again with it.
     */
    func signOutSessions(deviceIds: [String], password: String?) async throws 
    
    /**
     * Asks someone else to compare emoji, through our chat.
     */
    func verifyPerson(userId: String, listener: VerificationListener) async throws  -> Verification
    
    /**
     * Asks one of my other devices to verify with this one.
     */
    func verifySession(deviceId: String, listener: VerificationListener) async throws  -> Verification
    
    /**
     * Asks my other devices to verify this one. Any of them can answer.
     */
    func verifyThisDevice(listener: VerificationListener) async throws  -> Verification
    
}
