#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeXeniaClient: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = XeniaClient

    public static func lift(_ handle: UInt64) throws -> XeniaClient {
        return XeniaClient(unsafeFromHandle: handle)
    }

    public static func lower(_ value: XeniaClient) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> XeniaClient {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: XeniaClient, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeXeniaClient_lift(_ handle: UInt64) throws -> XeniaClient {
    return try FfiConverterTypeXeniaClient.lift(handle)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeXeniaClient_lower(_ value: XeniaClient) -> UInt64 {
    return FfiConverterTypeXeniaClient.lower(value)
}




/**
 * The signed-in person.
 */
public struct Account: Equatable, Hashable {
    public let userId: String
    public let displayName: String?
    /**
     * An `mxc://` URL; load it with `XeniaClient::load_avatar`.
     */
    public let avatarUrl: String?
    public let deviceId: String
    /**
     * The homeserver's address, like "https://matrix.example.org".
     */
    public let homeserver: String

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(userId: String, displayName: String?, 
        /**
         * An `mxc://` URL; load it with `XeniaClient::load_avatar`.
         */avatarUrl: String?, deviceId: String, 
        /**
         * The homeserver's address, like "https://matrix.example.org".
         */homeserver: String) {
        self.userId = userId
        self.displayName = displayName
        self.avatarUrl = avatarUrl
        self.deviceId = deviceId
        self.homeserver = homeserver
    }

    

    
}

#if compiler(>=6)
extension Account: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeAccount: FfiConverterRustBuffer {
    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> Account {
        return
            try Account(
                userId: FfiConverterString.read(from: &buf), 
                displayName: FfiConverterOptionString.read(from: &buf), 
                avatarUrl: FfiConverterOptionString.read(from: &buf), 
                deviceId: FfiConverterString.read(from: &buf), 
                homeserver: FfiConverterString.read(from: &buf)
        )
    }

    public static func write(_ value: Account, into buf: inout [UInt8]) {
        FfiConverterString.write(value.userId, into: &buf)
        FfiConverterOptionString.write(value.displayName, into: &buf)
        FfiConverterOptionString.write(value.avatarUrl, into: &buf)
        FfiConverterString.write(value.deviceId, into: &buf)
        FfiConverterString.write(value.homeserver, into: &buf)
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeAccount_lift(_ buf: RustBuffer) throws -> Account {
    return try FfiConverterTypeAccount.lift(buf)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeAccount_lower(_ value: Account) -> RustBuffer {
    return FfiConverterTypeAccount.lower(value)
}


/**
 * Something to send as a file.
 */
public struct Attachment: Equatable, Hashable {
    /**
     * A file on disk the app can read.
     */
    public let path: String
    public let filename: String
    public let mimetype: String
    public let size: UInt64?
    /**
     * For photos and videos.
