/**
 * A conversation, as the lists show it.
 */
public struct RoomSummary: Equatable, Hashable {
    public let id: String
    public let name: String
    /**
     * An `mxc://` URL: the room's photo, or for a DM the other person's.
     */
    public let avatarUrl: String?
    /**
     * Picks the avatar's color and initials when there's no photo: the other person's ID for a
     * DM, the room's ID otherwise.
     */
    public let avatarSeed: String
    /**
     * For a DM, the other person's user ID.
     */
    public let dmUserId: String?
    public let scope: Scope
    public let isDirect: Bool
    /**
     * A direct chat with exactly one other person.
     */
    public let isDm: Bool
    public let isEncrypted: Bool
    public let isFavourite: Bool
    /**
     * Where the person put this pin among the others: the favourite tag's `order`, from 0 to 1.
     */
    public let favouriteOrder: Double?
    public let isLowPriority: Bool
    public let isInvite: Bool
    public let isPublic: Bool
    /**
     * For invitations: who invited me.
     */
    public let inviterName: String?
    public let topic: String?
    /**
     * The room's address, like "#design:example.org".
     */
    public let alias: String?
    public let memberCount: UInt64
    public let unreadCount: UInt64
    public let mentionCount: UInt64
    public let isMarkedUnread: Bool
    public let isMuted: Bool
    /**
     * The room's own setting, or `AllMessages` when it has none (see `has_own_notification_mode`).
     */
    public let notificationMode: NotificationMode
    /**
     * The person chose a mode for this room. Without one, `effective_notification_mode` applies
     * the app's defaults.
     */
    public let hasOwnNotificationMode: Bool
    /**
     * Wants attention (counts toward the tab badge and the Unread filter).
     */
    public let isUnread: Bool
    public let unreadKind: UnreadKind
    public let pinnedEventIds: [String]
    public let preview: RoomPreview
    /**
     * When the latest activity happened, for sorting and the row's time. Zero when unknown.
     */
    public let timestampMs: Int64
    /**
     * Unsent text in the composer, shown as "Draft" in the list.
     */
    public let draft: String?
    /**
     * The latest message I sent is still sending, or failed.
     */
    public let lastSendState: SendState?

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(id: String, name: String, 
        /**
         * An `mxc://` URL: the room's photo, or for a DM the other person's.
         */avatarUrl: String?, 
        /**
         * Picks the avatar's color and initials when there's no photo: the other person's ID for a
         * DM, the room's ID otherwise.
         */avatarSeed: String, 
        /**
         * For a DM, the other person's user ID.
         */dmUserId: String?, scope: Scope, isDirect: Bool, 
        /**
         * A direct chat with exactly one other person.
         */isDm: Bool, isEncrypted: Bool, isFavourite: Bool, 
        /**
         * Where the person put this pin among the others: the favourite tag's `order`, from 0 to 1.
         */favouriteOrder: Double?, isLowPriority: Bool, isInvite: Bool, isPublic: Bool, 
        /**
         * For invitations: who invited me.
         */inviterName: String?, topic: String?, 
        /**
         * The room's address, like "#design:example.org".
         */alias: String?, memberCount: UInt64, unreadCount: UInt64, mentionCount: UInt64, isMarkedUnread: Bool, isMuted: Bool, 
        /**
         * The room's own setting, or `AllMessages` when it has none (see `has_own_notification_mode`).
         */notificationMode: NotificationMode, 
        /**
         * The person chose a mode for this room. Without one, `effective_notification_mode` applies
         * the app's defaults.
         */hasOwnNotificationMode: Bool, 
        /**
         * Wants attention (counts toward the tab badge and the Unread filter).
         */isUnread: Bool, unreadKind: UnreadKind, pinnedEventIds: [String], preview: RoomPreview, 
        /**
         * When the latest activity happened, for sorting and the row's time. Zero when unknown.
         */timestampMs: Int64, 
        /**
         * Unsent text in the composer, shown as "Draft" in the list.
         */draft: String?, 
        /**
         * The latest message I sent is still sending, or failed.
         */lastSendState: SendState?) {
        self.id = id
        self.name = name
        self.avatarUrl = avatarUrl
        self.avatarSeed = avatarSeed
        self.dmUserId = dmUserId
        self.scope = scope
        self.isDirect = isDirect
        self.isDm = isDm
        self.isEncrypted = isEncrypted
        self.isFavourite = isFavourite
        self.favouriteOrder = favouriteOrder
        self.isLowPriority = isLowPriority
        self.isInvite = isInvite
        self.isPublic = isPublic
        self.inviterName = inviterName
        self.topic = topic
        self.alias = alias
        self.memberCount = memberCount
        self.unreadCount = unreadCount
        self.mentionCount = mentionCount
        self.isMarkedUnread = isMarkedUnread
        self.isMuted = isMuted
        self.notificationMode = notificationMode
        self.hasOwnNotificationMode = hasOwnNotificationMode
        self.isUnread = isUnread
        self.unreadKind = unreadKind
        self.pinnedEventIds = pinnedEventIds
        self.preview = preview
        self.timestampMs = timestampMs
        self.draft = draft
        self.lastSendState = lastSendState
    }

    

    
}

