// Note that we don't yet support `indirect` for enums.
// See https://github.com/mozilla/uniffi-rs/issues/396 for further discussion.
/**
 * Where chat backup stands on this device.
 */

public enum BackupStatus: Equatable, Hashable {
    
    /**
     * Still finding out.
     */
    case checking
    /**
     * Backed up and unlocked here.
     */
    case on
    /**
     * Set up on another device; this one needs the recovery key to read older messages.
     */
    case needsKey
    /**
     * Not set up: encrypted messages can't be recovered on a new device.
     */
    case off





}

#if compiler(>=6)
extension BackupStatus: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeBackupStatus: FfiConverterRustBuffer {
    typealias SwiftType = BackupStatus

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> BackupStatus {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .checking
        
        case 2: return .on
        
        case 3: return .needsKey
        
        case 4: return .off
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: BackupStatus, into buf: inout [UInt8]) {
        switch value {
        
        
        case .checking:
            writeInt(&buf, Int32(1))
        
        
        case .on:
            writeInt(&buf, Int32(2))
        
        
        case .needsKey:
            writeInt(&buf, Int32(3))
        
        
        case .off:
            writeInt(&buf, Int32(4))
        
        }
    }
}


