// See https://github.com/mozilla/uniffi-rs/issues/396 for further discussion.
/**
 * What a message says, for one-line previews, reply quotes, thread summaries and notifications.
 */

public enum Body: Equatable, Hashable {
    
    /**
     * Text, with any formatting flattened to plain words on one line.
     */
    case text(text: String
    )
    /**
     * "/me waves": the app shows it after the sender's name.
     */
    case emote(text: String
    )
    case notice(text: String
    )
    case image(caption: String?
    )
    case video(caption: String?
    )
    case audio(caption: String?
    )
    case voice
    case file(name: String, caption: String?
    )
    case sticker(description: String
    )
    case poll(question: String
    )
    case location
    case gallery(count: UInt32
    )
    case deleted
    /**
     * Couldn't be decrypted (yet).
     */
    case encrypted
    case unsupported
    /**
     * An invitation to join (for a pushed invite).
     */
    case invite





}

