extension Body: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeBody: FfiConverterRustBuffer {
    typealias SwiftType = Body

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> Body {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .text(text: try FfiConverterString.read(from: &buf)
        )
        
        case 2: return .emote(text: try FfiConverterString.read(from: &buf)
        )
        
        case 3: return .notice(text: try FfiConverterString.read(from: &buf)
        )
        
        case 4: return .image(caption: try FfiConverterOptionString.read(from: &buf)
        )
        
        case 5: return .video(caption: try FfiConverterOptionString.read(from: &buf)
        )
        
        case 6: return .audio(caption: try FfiConverterOptionString.read(from: &buf)
        )
        
        case 7: return .voice
        
        case 8: return .file(name: try FfiConverterString.read(from: &buf), caption: try FfiConverterOptionString.read(from: &buf)
        )
        
        case 9: return .sticker(description: try FfiConverterString.read(from: &buf)
        )
        
        case 10: return .poll(question: try FfiConverterString.read(from: &buf)
        )
        
        case 11: return .location
        
        case 12: return .gallery(count: try FfiConverterUInt32.read(from: &buf)
        )
        
        case 13: return .deleted
        
        case 14: return .encrypted
        
        case 15: return .unsupported
        
        case 16: return .invite
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: Body, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .text(text):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(text, into: &buf)
            
        
        case let .emote(text):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(text, into: &buf)
            
        
        case let .notice(text):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(text, into: &buf)
            
        
        case let .image(caption):
            writeInt(&buf, Int32(4))
            FfiConverterOptionString.write(caption, into: &buf)
            
        
        case let .video(caption):
