public enum MessageContent: Equatable, Hashable {
    
    case text(blocks: [RichBlock], plain: String, kind: TextKind, isJumbo: Bool
    )
    case image(media: MediaInfo, caption: String?
    )
    case video(media: MediaInfo, durationMs: UInt64?, caption: String?
    )
    case audio(source: String, filename: String, durationMs: UInt64?, size: UInt64?, mimetype: String?, isVoice: Bool, caption: String?
    )
    case file(source: String, filename: String, size: UInt64?, mimetype: String?, caption: String?
    )
    case sticker(media: MediaInfo, description: String
    )
    case poll(question: String, answers: [PollAnswer], 
        /**
         * Votes show as they come in; otherwise only once the poll ends.
         */isDisclosed: Bool, 
        /**
         * How many answers each person may choose.
         */maxSelections: UInt32, 
        /**
         * People who have voted, each counted once.
         */voterCount: UInt32, isEnded: Bool, 
        /**
         * My poll, still open: I can end it.
         */canEnd: Bool
    )
    case location(geoUri: String, description: String?
    )
    case deleted
    /**
     * Couldn't be decrypted (yet): the key may still arrive from backup or another device.
     */
    case encrypted
    case unsupported





}

