extension MessageContent: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeMessageContent: FfiConverterRustBuffer {
    typealias SwiftType = MessageContent

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> MessageContent {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .text(blocks: try FfiConverterSequenceTypeRichBlock.read(from: &buf), plain: try FfiConverterString.read(from: &buf), kind: try FfiConverterTypeTextKind.read(from: &buf), isJumbo: try FfiConverterBool.read(from: &buf)
        )
        
        case 2: return .image(media: try FfiConverterTypeMediaInfo.read(from: &buf), caption: try FfiConverterOptionString.read(from: &buf)
        )
        
        case 3: return .video(media: try FfiConverterTypeMediaInfo.read(from: &buf), durationMs: try FfiConverterOptionUInt64.read(from: &buf), caption: try FfiConverterOptionString.read(from: &buf)
        )
        
        case 4: return .audio(source: try FfiConverterString.read(from: &buf), filename: try FfiConverterString.read(from: &buf), durationMs: try FfiConverterOptionUInt64.read(from: &buf), size: try FfiConverterOptionUInt64.read(from: &buf), mimetype: try FfiConverterOptionString.read(from: &buf), isVoice: try FfiConverterBool.read(from: &buf), caption: try FfiConverterOptionString.read(from: &buf)
        )
        
        case 5: return .file(source: try FfiConverterString.read(from: &buf), filename: try FfiConverterString.read(from: &buf), size: try FfiConverterOptionUInt64.read(from: &buf), mimetype: try FfiConverterOptionString.read(from: &buf), caption: try FfiConverterOptionString.read(from: &buf)
        )
        
        case 6: return .sticker(media: try FfiConverterTypeMediaInfo.read(from: &buf), description: try FfiConverterString.read(from: &buf)
        )
        
        case 7: return .poll(question: try FfiConverterString.read(from: &buf), answers: try FfiConverterSequenceTypePollAnswer.read(from: &buf), isDisclosed: try FfiConverterBool.read(from: &buf), maxSelections: try FfiConverterUInt32.read(from: &buf), voterCount: try FfiConverterUInt32.read(from: &buf), isEnded: try FfiConverterBool.read(from: &buf), canEnd: try FfiConverterBool.read(from: &buf)
        )
        
        case 8: return .location(geoUri: try FfiConverterString.read(from: &buf), description: try FfiConverterOptionString.read(from: &buf)
        )
        
        case 9: return .deleted
        
        case 10: return .encrypted
        
        case 11: return .unsupported
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: MessageContent, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .text(blocks,plain,kind,isJumbo):
            writeInt(&buf, Int32(1))
            FfiConverterSequenceTypeRichBlock.write(blocks, into: &buf)
            FfiConverterString.write(plain, into: &buf)
            FfiConverterTypeTextKind.write(kind, into: &buf)
            FfiConverterBool.write(isJumbo, into: &buf)
            
        
        case let .image(media,caption):
            writeInt(&buf, Int32(2))
            FfiConverterTypeMediaInfo.write(media, into: &buf)
            FfiConverterOptionString.write(caption, into: &buf)
            
        
        case let .video(media,durationMs,caption):
            writeInt(&buf, Int32(3))
            FfiConverterTypeMediaInfo.write(media, into: &buf)
            FfiConverterOptionUInt64.write(durationMs, into: &buf)
            FfiConverterOptionString.write(caption, into: &buf)
            
        
        case let .audio(source,filename,durationMs,size,mimetype,isVoice,caption):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(source, into: &buf)
            FfiConverterString.write(filename, into: &buf)
            FfiConverterOptionUInt64.write(durationMs, into: &buf)
            FfiConverterOptionUInt64.write(size, into: &buf)
            FfiConverterOptionString.write(mimetype, into: &buf)
            FfiConverterBool.write(isVoice, into: &buf)
            FfiConverterOptionString.write(caption, into: &buf)
            
        
        case let .file(source,filename,size,mimetype,caption):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(source, into: &buf)
            FfiConverterString.write(filename, into: &buf)
            FfiConverterOptionUInt64.write(size, into: &buf)
            FfiConverterOptionString.write(mimetype, into: &buf)
            FfiConverterOptionString.write(caption, into: &buf)
            
        
        case let .sticker(media,description):
            writeInt(&buf, Int32(6))
            FfiConverterTypeMediaInfo.write(media, into: &buf)
            FfiConverterString.write(description, into: &buf)
            
        
        case let .poll(question,answers,isDisclosed,maxSelections,voterCount,isEnded,canEnd):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(question, into: &buf)
            FfiConverterSequenceTypePollAnswer.write(answers, into: &buf)
            FfiConverterBool.write(isDisclosed, into: &buf)
            FfiConverterUInt32.write(maxSelections, into: &buf)
            FfiConverterUInt32.write(voterCount, into: &buf)
            FfiConverterBool.write(isEnded, into: &buf)
            FfiConverterBool.write(canEnd, into: &buf)
            
        
        case let .location(geoUri,description):
            writeInt(&buf, Int32(8))
            FfiConverterString.write(geoUri, into: &buf)
            FfiConverterOptionString.write(description, into: &buf)
            
        
        case .deleted:
            writeInt(&buf, Int32(9))
        
        
        case .encrypted:
            writeInt(&buf, Int32(10))
        
        
        case .unsupported:
            writeInt(&buf, Int32(11))
        
        }
    }
}


