    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> RichBlock {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .paragraph(spans: try FfiConverterSequenceTypeRichSpan.read(from: &buf)
        )
        
        case 2: return .heading(level: try FfiConverterUInt8.read(from: &buf), spans: try FfiConverterSequenceTypeRichSpan.read(from: &buf)
        )
        
        case 3: return .quote(spans: try FfiConverterSequenceTypeRichSpan.read(from: &buf)
        )
        
        case 4: return .code(text: try FfiConverterString.read(from: &buf), language: try FfiConverterOptionString.read(from: &buf)
        )
        
        case 5: return .listItem(marker: try FfiConverterString.read(from: &buf), depth: try FfiConverterUInt8.read(from: &buf), spans: try FfiConverterSequenceTypeRichSpan.read(from: &buf)
        )
        
        case 6: return .rule
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: RichBlock, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .paragraph(spans):
            writeInt(&buf, Int32(1))
            FfiConverterSequenceTypeRichSpan.write(spans, into: &buf)
            
        
        case let .heading(level,spans):
            writeInt(&buf, Int32(2))
            FfiConverterUInt8.write(level, into: &buf)
            FfiConverterSequenceTypeRichSpan.write(spans, into: &buf)
            
        
        case let .quote(spans):
            writeInt(&buf, Int32(3))
