        case let .listItem(marker,depth,spans):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(marker, into: &buf)
            FfiConverterUInt8.write(depth, into: &buf)
            FfiConverterSequenceTypeRichSpan.write(spans, into: &buf)
            
        
        case .rule:
            writeInt(&buf, Int32(6))
        
        }
    }
}


