/**
 * Where a verification stands.
 */

public enum VerificationState: Equatable, Hashable {
    
    /**
     * Sent; waiting for the other device to accept.
     */
    case requested
    /**
     * Someone asked to verify with this device: accept or decline.
     */
    case incoming
    /**
     * Both sides agreed; the emoji are being worked out.
     */
    case starting
    /**
     * Compare these with the other screen.
     */
    case compare(emojis: [SasEmoji], decimals: [UInt16]
    )
    /**
     * I said they match; waiting for the other side to say so too.
     */
    case confirmed
    case done
    case ended(reason: VerificationEnd
    )





}

#if compiler(>=6)
extension VerificationState: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeVerificationState: FfiConverterRustBuffer {
    typealias SwiftType = VerificationState

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> VerificationState {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .requested
        
        case 2: return .incoming
        
        case 3: return .starting
        
        case 4: return .compare(emojis: try FfiConverterSequenceTypeSasEmoji.read(from: &buf), decimals: try FfiConverterSequenceUInt16.read(from: &buf)
        )
        
        case 5: return .confirmed
        
        case 6: return .done
        
        case 7: return .ended(reason: try FfiConverterTypeVerificationEnd.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: VerificationState, into buf: inout [UInt8]) {
        switch value {
        
        
        case .requested:
            writeInt(&buf, Int32(1))
        
        
        case .incoming:
            writeInt(&buf, Int32(2))
        
        
        case .starting:
            writeInt(&buf, Int32(3))
        
        
        case let .compare(emojis,decimals):
            writeInt(&buf, Int32(4))
            FfiConverterSequenceTypeSasEmoji.write(emojis, into: &buf)
            FfiConverterSequenceUInt16.write(decimals, into: &buf)
            
        
        case .confirmed:
            writeInt(&buf, Int32(5))
        
        
        case .done:
            writeInt(&buf, Int32(6))
        
        
        case let .ended(reason):
            writeInt(&buf, Int32(7))
            FfiConverterTypeVerificationEnd.write(reason, into: &buf)
            
        }
    }
}


