        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .InvalidCredentials
        case 2: return .UserDeactivated
        case 3: return .RateLimited
        case 4: return .ServerUnreachable
        case 5: return .NotAMatrixServer
        case 6: return .InsecureServer
        case 7: return .SlidingSyncUnsupported
        case 8: return .PasswordLoginUnsupported
        case 9: return .NotSignedIn
        case 10: return .NotFound
        case 11: return .Forbidden(
            message: try FfiConverterString.read(from: &buf)
            )
        case 12: return .PasswordRequired
        case 13: return .InvalidRecoveryKey
        case 14: return .Generic(
            message: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: XeniaError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case .InvalidCredentials:
            writeInt(&buf, Int32(1))
        
        
        case .UserDeactivated:
            writeInt(&buf, Int32(2))
        
        
        case .RateLimited:
            writeInt(&buf, Int32(3))
        
        
        case .ServerUnreachable:
            writeInt(&buf, Int32(4))
        
        
        case .NotAMatrixServer:
            writeInt(&buf, Int32(5))
        
        
        case .InsecureServer:
            writeInt(&buf, Int32(6))
        
        
        case .SlidingSyncUnsupported:
            writeInt(&buf, Int32(7))
        
        
        case .PasswordLoginUnsupported:
            writeInt(&buf, Int32(8))
        
        
        case .NotSignedIn:
            writeInt(&buf, Int32(9))
        
        
        case .NotFound:
